   276	// for MASM syntax, 0x123 = 123h, 0xA123 = 0A123h
   277	// this function tell us if we need to have prefix 0 in front of a number
   278	static bool need_zero_prefix(uint64_t imm)
   279	{
   280	        // find the first hex letter representing imm
   281	        while(imm >= 0x10)
   282	                imm >>= 4;
   283	
   284	        if (imm < 0xa)
   285	                return false;
   286	        else    // this need 0 prefix
   287	                return true;
   288	}
